<script setup lang="ts">
const route = useRoute(); const router = useRouter(); const recipe = await $fetch<any>(`/api/recipes/${route.params.id}`); const name = ref(recipe.name); const ingredients = ref(recipe.ingredients.map((x: any) => x.text)); const steps = ref(recipe.steps.map((x: any) => x.text)); const error = ref(''); const saving = ref(false); const imageError = ref('')
async function save() { saving.value = true; try { await $fetch('/api/recipes', { method: 'POST', body: { action: 'update', id: recipe.id, revision: recipe.revision, name: name.value, itemId: recipe.itemId, ingredients: ingredients.value.filter(Boolean), steps: steps.value.filter(Boolean) } }); await router.push(`/recipes/${recipe.id}`) } catch (cause: any) { error.value = cause?.data?.message ?? 'Could not save recipe.' } finally { saving.value = false } }
function add(list: string[]) { list.push('') }
async function upload(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file || recipe.images.length >= 2) return; if (!file.type.startsWith('image/')) { imageError.value = 'Choose an image file.'; return }; const reader = new FileReader(); reader.onload = async () => { try { await $fetch('/api/recipes', { method: 'POST', body: { action: 'image', id: recipe.id, slot: recipe.images.length + 1, mimeType: file.type, imageData: String(reader.result), width: 0, height: 0 } }); recipe.images.push({ id: crypto.randomUUID(), imageData: reader.result }); imageError.value = '' } catch (cause: any) { imageError.value = cause?.data?.message ?? 'Could not save image.' } }; reader.readAsDataURL(file) }
</script>
<template><main class="prep-page max-w-3xl"><NuxtLink :to="`/recipes/${recipe.id}`" class="text-sm text-stone-500">← Recipe</NuxtLink><h1 class="prep-title mt-4">Edit recipe</h1><p v-if="error" role="alert" class="mt-3 text-sm text-red-700">{{ error }}</p><input v-model="name" class="prep-input mt-6" /><div class="mt-6 grid gap-5 md:grid-cols-2"><section class="prep-card p-5"><h2 class="text-lg font-semibold">Ingredients</h2><div v-for="(_, index) in ingredients" :key="index" class="mt-3"><input v-model="ingredients[index]" class="prep-input" @keydown.enter.prevent="add(ingredients)" /></div><button class="prep-secondary mt-3" @click="add(ingredients)">Add ingredient</button></section><section class="prep-card p-5"><h2 class="text-lg font-semibold">Steps</h2><div v-for="(_, index) in steps" :key="index" class="mt-3"><textarea v-model="steps[index]" rows="2" class="prep-input"></textarea></div><button class="prep-secondary mt-3" @click="add(steps)">Add step</button></section></div><button class="prep-primary mt-6" :disabled="saving" @click="save">{{ saving ? 'Saving…' : 'Save changes' }}</button></main></template>
